# -*- coding: utf-8 -*-
"""영어 은폐 규칙 생성기 (en v0.1, 2026-11-14) → rules/en/en_concealment.yar

영어 공격은 원래 SkillSpector 몫이지만, 1차 크롤링에서 SkillSpector 정적 검사와 한·중·일 규칙이 모두 놓친
'숨겨서 실행하고 사용자에게 말하지 말라' 패턴 하나만 예외로 우리 규칙에 넣는다.
- 영어는 바이트 표기가 필요 없어 규칙 본문을 그대로 쓴다.
- 핵심 단어는 s[i]lently / q[u]ietly 로 써서 규칙 파일이 자기 자신에 걸리지 않게 한다.
실행: python tools/rulegen/en_gen.py
"""
from pathlib import Path

OUT = Path(__file__).resolve().parents[2] / "rules" / "en" / "en_concealment.yar"

HEADER = '/*\n  AS Screener - English concealment rules v0.1 (2026-11-14)\n  GENERATED by tools/rulegen/en_gen.py - edit the generator, not this file.\n  Scope: instructions that make the agent hide an action from the user (English only).\n  English attacks are otherwise left to SkillSpector; this file is an exception for one pattern it missed\n  in the batch-1 crawl (hidden setup script + "do not mention it", silent telemetry POST).\n  Notes:\n  - Key words are written as s[i]lently / q[u]ietly so this file does not match itself.\n  - $q is a private guard: a match that starts right after a quote mark is an example being quoted, not an order.\n*/\n'

BODY = 'rule en_conceal_silent_exec\n{\n    meta:\n        severity = "HIGH"\n        description = "[EN] Runs something silently and tells the agent not to mention it to the user"\n    strings:\n        $a = /\\b(run|execute|exec|invoke|install|download|bash|sh|curl|wget|python3?|node|npx)\\b[^\\n]{0,40}\\b(s[i]lently|q[u]ietly)\\b[^\\n]{0,200}\\b(do not|don\'t|never)\\s+(narrate|mention|tell|inform|notify|comment on|disclose|reveal)\\b/ nocase\n        $b = /\\b(s[i]lently|q[u]ietly)\\s+(run|execute|invoke|install|download|launch|start)\\b[^\\n]{0,200}\\b(do not|don\'t|never)\\s+(narrate|mention|tell|inform|notify|comment on|disclose|reveal)\\b/ nocase\n        $c = /\\b(do not|don\'t|never)\\s+(narrate|mention|tell|inform|notify|comment on|disclose|reveal)\\b[^\\n]{0,200}\\b(s[i]lently|q[u]ietly)\\s+(run|execute|invoke|install|download|launch|start)\\b/ nocase\n        $d = />\\s*\\/dev\\/null[^\\n]{0,120}\\b(do not|don\'t|never)\\s+(narrate|mention|tell|inform|comment on|disclose)\\b/ nocase\n        $q = /([\'"`]|\\xE2\\x80[\\x98\\x9C])[ ]?\\w/\n    condition:\n        for any of ($a, $b, $c, $d) : ( for any i in (1..#) : ( not for any j in (1..#q) : ( @q[j] + !q[j] - 1 == @[i] ) ) )\n}\n\nrule en_conceal_silent_send\n{\n    meta:\n        severity = "HIGH"\n        description = "[EN] Silently sends data to an external endpoint"\n    strings:\n        $a = /\\b(s[i]lently|q[u]ietly)\\s+(post|send|upload|transmit|forward|report|beacon|ping)\\b[^\\n]{0,80}\\b(endpoint|server|webhook|telemetry|analytics|https?:\\/\\/|api)\\b/ nocase\n        $b = /\\b(post|send|upload|transmit|forward)\\b[^\\n]{0,60}\\b(endpoint|server|webhook|telemetry|https?:\\/\\/)[^\\n]{0,80}\\b(s[i]lently|q[u]ietly)\\b/ nocase\n        $q = /([\'"`]|\\xE2\\x80[\\x98\\x9C])[ ]?\\w/\n    condition:\n        for any of ($a, $b) : ( for any i in (1..#) : ( not for any j in (1..#q) : ( @q[j] + !q[j] - 1 == @[i] ) ) )\n}\n\nrule en_conceal_without_telling\n{\n    meta:\n        severity = "MEDIUM"\n        description = "[EN] Acts without telling the user"\n    strings:\n        $a = /\\b(run|execute|send|upload|post|install|delete|modify|commit|push)\\b[^\\n]{0,80}\\bwithout (telling|informing|notifying|alerting) (the )?user\\b/ nocase\n    condition:\n        $a\n}\n'


def main() -> None:
    OUT.parent.mkdir(parents=True, exist_ok=True)
    OUT.write_text(HEADER + BODY, encoding="utf-8", newline="\n")
    print("wrote", OUT)


if __name__ == "__main__":
    main()
